/// <summary>Formulario "Publicar comentario". 1 estrella = 2 puntos de Valoracion.puntuacion (0–10).</summary>
public sealed class NuevaValoracionViewModel
{
    [Required(ErrorMessage = "Escribe tu comentario.")]
    [StringLength(1000, ErrorMessage = "El comentario no puede superar los {1} caracteres.")]
    [Display(Name = "Tu comentario")]
    public string Texto { get; set; } = string.Empty;

    [Range(1, 5, ErrorMessage = "Elige una puntuación de 1 a 5 estrellas.")]
    [Display(Name = "Tu puntuación")]
    public int Estrellas { get; set; }
}

/// <summary>Página Crear un videojuego (crear-videojuego.html).</summary>
public sealed class NuevoVideojuegoViewModel
{
    [Required(ErrorMessage = "El título es obligatorio.")]
    [StringLength(120, ErrorMessage = "El título no puede superar los {1} caracteres.")]
    [Display(Name = "Título")]
    public string Titulo { get; set; } = string.Empty;

    [Display(Name = "Descripción")]
    public string? Texto { get; set; }

    [Url(ErrorMessage = "Introduce una URL válida (https://…).")]
    [Display(Name = "Enlace externo")]
    public string? Enlace { get; set; }

    [Display(Name = "Imagen")]
    public IFormFile? Imagen { get; set; }

    public List<int> CategoriaIds { get; set; } = new();

    [BindNever, ValidateNever]
    public List<CategoriaOpcionViewModel> Categorias { get; set; } = new();
}

